python3 - <<'PY'
import openpyxl, os, re, sys, zipfile
out='/root/output/result.xlsx'
src='/root/data/workbook.xlsx'
errors=[]
wb_src=openpyxl.load_workbook(src, data_only=False)
wb2 = openpyxl.load_workbook(out, data_only=False)
ws = wb2['Task']
print('Exists:', os.path.exists(out), 'Size:', os.path.getsize(out) if os.path.exists(out) else None)
print('Sheets:', wb2.sheetnames)
if wb2.sheetnames != wb_src.sheetnames:
    errors.append(f'Sheet mismatch: {wb2.sheetnames} != {wb_src.sheetnames}')
print('\nRequested spot-check cells:')
for r in [12,19,26,35,42,46,47,50]:
    for c in range(8,13):  # H=8 .. L=12
        cell = ws.cell(row=r, column=c)
        print(cell.coordinate, cell.value)

# Full target validation
lookup_rows = list(range(12,18)) + list(range(19,25)) + list(range(26,32))
for r in lookup_rows:
    for c in range(8,13):
        val=ws.cell(r,c).value
        coord=ws.cell(r,c).coordinate
        if not (isinstance(val,str) and val.startswith('=INDEX(') and 'MATCH(' in val and 'Data!' in val and 'XLOOKUP' not in val and '#NAME?' not in val):
            errors.append(f'Bad lookup {coord}: {val!r}')
for r in range(35,41):
    for c in range(8,13):
        val=ws.cell(r,c).value
        if not (isinstance(val,str) and val.startswith('=') and '/' in val and '*100' in val):
            errors.append(f'Bad balance {ws.cell(r,c).coordinate}: {val!r}')
expected_funcs={42:'MIN',43:'MAX',44:'MEDIAN',45:'AVERAGE',46:'PERCENTILE',47:'PERCENTILE'}
for r,func in expected_funcs.items():
    for c in range(8,13):
        val=ws.cell(r,c).value
        if not (isinstance(val,str) and val.startswith(f'={func}(')):
            errors.append(f'Bad stat {ws.cell(r,c).coordinate}: {val!r}')
for c in range(8,13):
    val=ws.cell(50,c).value
    if not (isinstance(val,str) and val.startswith('=SUMPRODUCT(') and '/SUM(' in val):
        errors.append(f'Bad weighted {ws.cell(50,c).coordinate}: {val!r}')
# No macro parts
with zipfile.ZipFile(out) as z:
    macro_parts=[n for n in z.namelist() if 'vbaProject' in n or n.endswith('.bin')]
print('\nMacro/bin parts:', macro_parts)
if macro_parts:
    errors.append(f'Macro/bin parts found: {macro_parts}')
# Confirm formula text markers in all target cells
all_targets=[]
for block in [lookup_rows, range(35,41), range(42,48), [50]]:
    for r in block:
        for c in range(8,13):
            all_targets.append(ws.cell(r,c).coordinate)
non_formula=[coord for coord in all_targets if not (isinstance(ws[coord].value,str) and ws[coord].value.startswith('='))]
print('Target formula cell count:', len(all_targets), 'Non-formula targets:', non_formula)
if non_formula:
    errors.append(f'Non-formula targets: {non_formula}')
# Formula syntax spot-check exact expected examples
print('\nExact syntax spot checks:')
for coord in ['H12','L17','H35','L40','H42','L47','H50','L50']:
    print(coord, ws[coord].value)
if errors:
    print('\nVALIDATION FAILED')
    for e in errors: print('ERROR:', e)
    sys.exit(1)
print('\nVALIDATION PASSED')
